import type Confetti from "./../ui/Confetti.svelte";
import { As } from '../misc/as-state'
import { helpers, type Partial2 } from '../misc/helpers'

interface Tag {
    text: string;
    html: HTMLElement | null;
}

interface Ui {
    name: string;
    switchTo: string;
    switchTo2: string;
    group: string;
    lesson: string;
    connected: boolean;
    plusMinus: boolean;
    tag: {
        deviceId: Tag;
        profile: Tag;
        version: Tag;
        codename: Tag;
        status: Tag;
        help: Tag;
    }
    confetti: Confetti | null;
}

interface MyUi extends Ui {
    update(values: Partial2<Ui>): void;
}

export const ui: MyUi = (() => {
    let empty = () => ({text: "", html: null});

    let state: Ui = $state({
        name: "",
        switchTo: "",
        switchTo2: "",
        group: "",
        lesson: "",
        connected: false,
        plusMinus: true,
        tag: {
            deviceId: empty(),
            profile: empty(),
            version: empty(),
            codename: empty(),
            status: empty(),
            help: empty(),
        },
        confetti: null
    });

    function update(values: Partial2<Ui>) {
        helpers.deepAsign(state, values);
    }

    return As(state, {
        update
    });
})();

