<script lang="ts">
    import type { Snippet } from "svelte";

    interface Props {
        clicked: () => void;
        children: Snippet;
        disabled?: boolean;
    }

    let {
        clicked, 
        children,
        disabled = false, 
    }: Props = $props();

    function onclick() {
        if (!disabled)
            clicked();
    }
</script>

<button class="panel" {onclick}
    class:enabled={!disabled}
>
    {@render children()}
</button>

<style>
    .panel {
        cursor: pointer;
        width: 100%;
        height: 100%;
        transition: transform 0.2s;
    }

    .panel.enabled:active {
        transform: scale(0.95);
    }
</style>