import { logger } from '../misc/logger';
import { config } from '../misc/config';
import { ably, type Client, type CsProtocol } from '../misc/ably';
import { As } from "../misc/as-state";
import { lenta } from './lenta.svelte'

interface MyPoll {
    clients: Client[];
    lenta: typeof lenta;
    init(): void;
    backFromCache(): void;
    clearCache(client: Client): void;
    updateProfileAlias(msg: CsProtocol["alias-is-edited"]): void;
    clearProfileAlias(msg: CsProtocol["alias-is-cleared"]): void;
    answer(msg: CsProtocol["answer"]): void;
    congrats(client: Client): void;
    gainPoints(client: Client, points: number): void;
}

export const poll: MyPoll = (() => {
    let log = logger.make("poll-main");

    let state = $state({
        clients: [] as Client[] 
    });

    function ably_reconnect() {
        log.info(() => "connecting to ably...");

        ably.connect();

        ably.trackPresence(clients => state.clients = clients);

        ably.enter({
            deviceId: config.deviceId,
            iAmATeacher: true,
            profiles: [],
            hostId: 1
        });

        ably.subscribe(() => true,
            ["alias-is-edited", updateProfileAlias],
            ["alias-is-cleared", clearProfileAlias],
            ["answer", answer],
        );
    }

    function init() {
        ably_reconnect();
    }

    function backFromCache() {
        ably_reconnect();
    }

    function clearCache(client: Client) {
        ably.publish("clear-cache", {
            codename: client.codename,
        });
    }

    function updateProfileAlias(msg: CsProtocol["alias-is-edited"]) {
        log.info(() => msg);
        ably.publish("set-profile-alias", msg);
    }

    function clearProfileAlias(msg: CsProtocol["alias-is-cleared"]) {
        log.info(() => msg);
        ably.publish("clear-profile-alias", {
            profileId: msg.profileId
        });
    }

    function answer(msg: CsProtocol["answer"]) {
        lenta.store(msg.profileId, msg.value);
    }

    function congrats(client: Client) {
        ably.publish("congrats", {
            codename: client.codename,
            message: "Well done!",
        });
    }

    function gainPoints(client: Client, points: number) {
        ably.publish("gain-points", {
            codename: client.codename,
            points,
        });
    }

    return As(state, {
        lenta,
        init,
        backFromCache,
        clearCache,
        updateProfileAlias,
        clearProfileAlias,
        answer,
        congrats,
        gainPoints,
    });
})();
