type MakeMsg = () => string | object;
type Severity = "none" | "error" | "warn" | "info" | "trace";

interface LogMsg {
    topic: string;
    severity: Severity;
    funcName: string;
    data: string | {};
}

interface MyLogger {
    error(makeMsg: MakeMsg): void;
    warn(makeMsg: MakeMsg): void;
    info(makeMsg: MakeMsg): void;
    trace(makeMsg: MakeMsg): void;
}

interface LogFactory {
    make(topic: string, severity?: Severity): MyLogger;
}

export const logger: LogFactory = (() => {
    let order: Record<Severity, number> = {
        none:  0,
        error: 1,
        warn:  2,
        info:  3,
        trace: 4
    };

    let config = new Map<string, Severity>([
//        ["ably", "none"],
//        ["cs-main", "none"],
//        ["poll-main", "none"],
    ]);

    let nullLogger: MyLogger = {
        error: () => {},
        warn: () => {},
        info: () => {},
        trace: () => {},
    }

    function getCallerFuncName(n: number): string | undefined {
        let stack = new Error().stack;
        if (!stack) return undefined;

        let split = stack.split("\n");
        if (split.length < 5) return undefined;

        let words = split[n].trim().split(/\s+/);
        if (words.length < 2) return undefined;

        let caller = words[1];
        let tokens = caller.split('.');

        let funcName = tokens.length > 1 ? tokens[1] : caller;
        if ([..."?=:"].some(ch => funcName.includes(ch))) return undefined;

        return funcName;
    }

    function makeLogger(topic: string, logSeverity: Severity) {
        function log(severity: Severity, makeMsg: MakeMsg) {
            if (order[severity] > order[logSeverity])
                return;

            let data = makeMsg();
            let funcName = getCallerFuncName(4) ?? "unknown";
            
            let msg: LogMsg = {
                topic, severity, funcName, data
            }

            let caller = funcName !== "unknown" ? `.${funcName}` : "";
            let site = `${msg.topic}${caller}:`;
            
            console.log(site, msg.data);
        }

        return {
            error: (makeMsg: MakeMsg) => log("error", makeMsg),
            warn: (makeMsg: MakeMsg) => log("warn", makeMsg),
            info: (makeMsg: MakeMsg) => log("info", makeMsg),
            trace: (makeMsg: MakeMsg) => log("trace", makeMsg),
        }
    }

    function make(topic: string, severity?: Severity) {
        severity = severity || config.get(topic) || "info";

        if (severity === "none")
            return nullLogger;

        return makeLogger(topic, severity);
    }

    return {
        make
    } as const;
})();