<script lang="ts">
    import { browser } from '../misc/browser';
    import { config } from '../misc/config';
    import { type Client } from '../misc/ably';
    import SvgText from "../ui/SvgText.svelte";
    import AsInput from '../ui/AsInput.svelte';
    import { poll } from './poll-main.svelte';

    poll.init();
    browser.onBackFromCache(poll.backFromCache);

    let lenta = poll.lenta;

    function client2str(cli: Client) {
        let str = cli.alias || cli.codename;
        return str;
    }

    function beforeAliasEdit(cli: Client) {
        if (cli.alias === cli.codename) {
            cli.alias = ""
        }
    }

    function afterAliasEdit(cli: Client) {
        if (cli.alias.trim() === "") {
            cli.alias = cli.codename;
            poll.clearProfileAlias({
                profileId: cli.profileId
            });
            return;
        }
        poll.updateProfileAlias({
            alias: cli.alias,
            profileId: cli.profileId 
        })
    }
</script>

{#snippet answer(cli: Client)}
    {@const answer = lenta.answers.get(cli.profileId)}
    {#if answer}
        {@const color = answer === 'yes' ? "badge-success" : "badge-error"}
        <div class="badge {color}">{answer}</div>
    {/if}
{/snippet}

{#snippet peers(count: number)}
    {#if count > 1}
        <kbd class="kbd">{count}</kbd>
    {/if}
{/snippet}

{#snippet btnPointsGain(cli: Client)}
    <button class="btn btn-xs points-gain"
        onclick={() => poll.gainPoints(cli, 100)}
    >
        +100
    </button>
{/snippet}

{#snippet btnClearCache(cli: Client)}
    {#if config.btnClearCache}
        <button class="btn btn-xs btn-active btn-warning clear-cache"
            onclick={() => poll.clearCache(cli)}
        >
            Clear cache
        </button>
    {/if}
{/snippet}

{#snippet client(cli: Client)}
    <div>
        <!-- svelte-ignore a11y_click_events_have_key_events -->
        <!-- svelte-ignore a11y_no_static_element_interactions -->
        <div onclick={() => poll.congrats(cli)}>
            <AsInput bind:value={cli.alias}
                beforeEdit={() => beforeAliasEdit(cli)}
                afterEdit={() => afterAliasEdit(cli)}
            >
                <SvgText text={client2str(cli)} bgColor="#ffec99" />
            </AsInput>
        </div>
        <div class="controls">
            <div class="badge badge-xg bg-blue-50">{cli.codename}</div>
            {@render peers(cli.peerCount)}
            {@render answer(cli)}
            {@render btnPointsGain(cli)}
            {@render btnClearCache(cli)}
        </div>
    </div>
{/snippet}

<div class="grid">
    {#each poll.clients as cli}
        {@render client(cli)}
    {/each}
</div>

<style>
    .grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: 10px;
    }
    .controls {
        display: flex;
        flex-wrap: wrap;
        gap: 10px;
        padding: 0 10px;
    }
    .btn {
        flex: 0 0 80px;
    }
    .points-gain {
        flex: 0 0 auto;
        width: fit-content;
    }
    .clear-cache {
        margin-left: auto;
    }
</style>
