import { SvelteMap } from "svelte/reactivity";

interface MyLenta {
    answers: SvelteMap<string, string>;
    store(profileId: string, answer: string): void;
}

export const lenta: MyLenta = (() => {
    let answers = new SvelteMap<string, string>();

    function store(profileId: string, answer: string) {
        answers.set(profileId, answer);
    }

    return {
        answers,
        store
    }
})();