<script lang="ts">
    import type { Snippet } from "svelte";
    import EditIcon from './svg/EditIcon.svg.svelte'

    interface Props {
        value: string;
        children: Snippet;
        beforeEdit?: () => void;
        afterEdit?: () => void;
    }

    let {
        value = $bindable(),
        children,
        beforeEdit,
        afterEdit
    }: Props = $props();

    let input: HTMLInputElement;
    let div: HTMLDivElement;

    let focused = $state(false);

    function focus(event: MouseEvent) {
        event.preventDefault();
        beforeEdit?.();
        input.focus();
        focused = true;
    }

    function blur() {
        afterEdit?.();
        focused = false;
    }

    function keydown(e: KeyboardEvent) {
        if (e.key === "Enter") {
            e.preventDefault();
            input.blur();
        }
    }
</script>

<!-- svelte-ignore a11y_no_static_element_interactions -->
<div 
    class="container"
    class:focused
    oncontextmenu = {focus}
    bind:this = {div}
>
    {@render children()}

    <div class="edit-icon">
        <svg onclick={focus}
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 32 32"
            width="32"
            height="32"
            fill="none"
            aria-hidden="true">
            <path
                d="M6 26l2-8L21 5a3 3 0 0 1 4 0l2 2a3 3 0 0 1 0 4L14 24l-8 2z"
                stroke="currentColor"
                stroke-width="2.5"
                stroke-linecap="round"
                stroke-linejoin="round"
            />
            <path
                d="M19 7l6 6M8 18l6 6"
                stroke="currentColor"
                stroke-width="2.5"
            />
        </svg>
    </div>

    <input
        bind:this={input}
        bind:value
        onblur={blur}
        onkeydown={keydown}
        class="front"
        type="text"
        autocomplete="off"
        aria-label="Text input"
        enterkeyhint="go"
    />
</div>


<style>
    .container {
        position: relative;
        width: 100%;
        height: 100%;
        user-select: none;
        -webkit-user-select: none;
        -webkit-touch-callout: none;
    }

    .focused {
        border-radius: 16px;
        box-shadow: inset 0 0 0 16px black;
    }

    .front {
        position: absolute;
        inset: 0;
        padding: 0;
        border: 0;
        background: transparent;
        color: transparent;
        caret-color: transparent;
        font-size: 16px;
        pointer-events: none;
    }

    .front:focus {
        outline: none;
    }

    .edit-icon {
        height: 50%;
        position: absolute;
        right: 2%;
        bottom: 10%;
        z-index: 2;
    }
</style>
