import { makeCodename } from "./codename-generator"; 
import { getCached } from "./get-cached"; 

export type Partial2<T> = {
    [P in keyof T]?:
        T[P] extends object ? Partial2<T[P]> : T[P];
}

interface Helpers {
    getFileName(path: string): string | undefined;
    getFileNameWithoutExtension(path: string): string;
    makeId(noOfSegments: number): string;
    makeCodename: typeof makeCodename;
    getCached: typeof getCached;
    deepAsign<T extends object>(target: T, src: Partial2<T>): void;
}

export const helpers: Helpers = (() => {
    function getFileName(path: string) {
        return path.replaceAll('\\', '/').split('/').pop();
    }

    function getFileNameWithoutExtension(path: string) {
        return path.replaceAll('\\', '/').split('/').pop()!.split('.')[0];
    }

    function makeId(noOfSegments: number) {
        let diggits = "0123456789";
        let letters = "abcdefghijklmnopqrstuvwxyz";
        let segments: string[] = [];
        let count = 0;
        
        let dgt = () => diggits.charAt(Math.floor(Math.random() * diggits.length));
        let ltr = () => letters.charAt(Math.floor(Math.random() * letters.length));

        while (count++ < noOfSegments) {
            segments.push(count % 2 === 0 ?
                `${dgt()}${dgt()}` : `${ltr()}${ltr()}`);
        }

        let id = segments.join('.');

        return id;
    }

    function deepAsign(target: any, src: any) {
        for (let key of Object.keys(src)) {
            let sourceValue = src[key];
            let targetValue = target[key];

            if (Array.isArray(sourceValue)) {
                if (targetValue === null || targetValue === undefined) {
                    targetValue = [];
                    target[key] = targetValue;
                }
                else if (!Array.isArray(targetValue)) {
                    throw new TypeError(`Target property "${key}" is not an array`);
                }

                targetValue.splice(0, targetValue.length, ...sourceValue);
            }
            else if (sourceValue !== null && typeof sourceValue === "object") {
                if (targetValue === null || targetValue === undefined) {
                    targetValue = {};
                    target[key] = targetValue;
                }
                else if (typeof targetValue !== "object" || Array.isArray(targetValue)) {
                    throw new TypeError(`Target property "${key}" is not an object`);
                }

                deepAsign(targetValue, sourceValue);
            }
            else {
                target[key] = sourceValue;
            }
        }

        return target;
    }    

    return {
        getFileName,
        getFileNameWithoutExtension,
        makeId,
        makeCodename,
        getCached,
        deepAsign,
    } as const;
})();
