import { helpers } from "./helpers";

export const config = (() => {
    interface UrlArgs extends Record<string, string | boolean> {
        app: string;
        channel: string;
        group: string;
        lesson: string;
        key: string;
        btnClearCache: boolean;
    }

    let locals = helpers.getCached("console-locals", () => ({
        deviceId: helpers.makeId(4),
        codenames: [
            helpers.makeCodename(),
            helpers.makeCodename(),
            helpers.makeCodename()
        ]
    }));

    function parseUrlArgs(): UrlArgs {
        function toVarName(name: string): string {
            let result = name.replace(
                /[-_]+(.)?/g,
                (_, char: string | undefined) => char?.toUpperCase() ?? ""
            );
            return result.charAt(0).toLowerCase() + result.slice(1);
        }

        let args: UrlArgs = {
            app: "console",
            channel: "cs-console:presence",
            group: "2-19",
            lesson: "SQL introduction",
            key: "-4ftTQ.1tGBgQ:knDkgiTP0i4HlHBD1lE0SA5dK9w2tBk-3bf3Bi8aXXc",
            btnClearCache: false,
        };

        let segments = window.location.pathname
            .split("/")
            .filter(segment => segment !== "")
            .map(decodeURIComponent);

        if (segments.length === 0) {
            args["root"] = "cs";
        }
        else {
            args["root"] = segments[0];

            for (let i = 0; i < segments.length - 1; i++) {
                args[toVarName(segments[i])] = segments[i + 1];
            }

            args[segments.at(-1)!] = window.location.search;
        }

        for (let [name, strValue] of new URLSearchParams(window.location.search)) {
            console.log({name, value: strValue});
            let value = strValue === "" ? true : strValue;
            args[toVarName(name)] = value;
        }

        return args;
    }

    function clearLocals() {
        localStorage.clear();
    }

    return {
        ...locals,
        ...parseUrlArgs(),
        clearLocals,
    } as const;
})();
